 'pagina.rrhh-timbradas.marcar', 'pagina.rrhh-timbradas.equipo', 'rrhh-timbradas.equipo.exportar', 'pagina.rrhh-timbradas.horarios', 'rrhh-timbradas.horarios.editar', 'rrhh-timbradas.horarios.ajustes', 'pagina.dotaciones', 'pagina.dotaciones.entregas', 'dotaciones.entregas.registrar', 'pagina.dotaciones.productos', 'dotaciones.productos.gestionar', 'dotaciones.productos.ingreso', 'pagina.dotaciones.planes', 'dotaciones.planes.gestionar', 'pagina.perfil', 'pagina.sistema', 'sistema.sync.usar', 'datos.cedula.ver', 'datos.contacto.ver', 'rrhh.timbrada.obligatoria', 'rrhh-timbradas.marcar.obligatoria', 'pagina.usuarios', 'pagina.usuarios.usuarios', 'reportes.ver', 'reportes.excel', 'reportes.pdf', 'pagina.reportes']::TEXT[], 'GLOBAL', 'ADMINISTRACION', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
